  +      approveExtension({ kind: "project-hooks", scope: project.id.scope, key: project.id.key, sha256, approvedAt: new Date().toISOString(), summary: `${count} hook${count === 1 ? "" : "s"}`, ...(project.files.length ? { files: project.files } : {}) });
