    [home, [`.config/nexus/hooks.json`, `./.config/nexus/hooks.json`, `.config/nexus/extension_trust.json`, `.config/../.config/nexus/hooks.json`, hooks, `.config/nexus/hooks.json/`, `.CONFIG/NEXUS/HOOKS.JSON`]],
    [path.join(home, ".config"), [`nexus/hooks.json`, `nexus/extension_trust.json`, `./nexus/hooks.json`]],
    [cfg, [`hooks.json`, `extension_trust.json`, `./hooks.json`]],
