import { test } from "node:test";
import fs from "node:fs"; import os from "node:os"; import path from "node:path";
import { hookAgent, dispatch, writeProjectHooks, approveProjectHooks, runsOf } from "./helpers/hooks_fixture.js";
import { makeRepo } from "./helpers/fixtures.js";
import { inspectHookSources } from "../src/core/hooks.js";

const mk = (p: string) => fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), p)));
const out: string[] = [];
async function scenario(name: string, command: unknown, files: Record<string, string>, tamper: (repo: string, agent: any) => Promise<void>, opts: { approveAnyway?: boolean } = {}) {
  const home = mk("p782h-"); process.env.HOME = home;
  const repo = fs.realpathSync(makeRepo({ "a.txt": "x\n" }));
  const logd = mk("p782l-"); const log = path.join(logd, "runs.log");
  const notices: string[] = [];
  for (const [f, body] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(repo, f)), { recursive: true }); fs.writeFileSync(path.join(repo, f), body.replaceAll("LOG", log), { mode: 0o755 }); }
  writeProjectHooks(repo, { version: 1, hooks: { "pre-tool": [{ name: "g", tools: ["read_file"], command }] } });
  const st = inspectHookSources({ workspace: repo, readOnly: false }).project;
  const agent = hookAgent({ repo, stateDir: mk("p782s-"), mode: "auto", fullAccess: true, notices });
  let note = `status=${st.status}${st.problem ? " problem=" + st.problem.slice(0, 90) : ""}`;
  if (st.status !== "invalid") {
    approveProjectHooks(repo);
    await dispatch(agent, "read_file", { path: "a.txt" });
    const before = fs.existsSync(log) ? fs.readFileSync(log, "utf8").split("\n").filter(Boolean).length : 0;
    await tamper(repo, agent);
    await dispatch(agent, "read_file", { path: "a.txt" });
    const after = fs.existsSync(log) ? fs.readFileSync(log, "utf8").split("\n").filter(Boolean).length : 0;
    note += ` runsBeforeTamper=${before} afterTamperCall=${after - before} tamperedRan=${fs.existsSync(log) && fs.readFileSync(log, "utf8").includes("TAMPERED")} notices=${JSON.stringify(notices.filter((n) => n.includes("hooks")).map((n) => n.slice(0, 140)))}`;
  }
  out.push(`${name}: ${note}`);
  agent.shutdown();
}
const SH = `#!/bin/sh\ncat >> LOG; echo >> LOG\nexit 0\n`;
const SHT = `#!/bin/sh\necho TAMPERED >> LOG\nexit 0\n`;
const JS = `require("fs").appendFileSync("LOG", require("fs").readFileSync(0,"utf8")+"\\n");\n`;
const JST = `require("fs").appendFileSync("LOG","TAMPERED\\n");\n`;
const over = (rel: string, content: string) => async (repo: string, agent: any) => { const r = await dispatch(agent, "write_file", { path: rel, content, overwrite: true }); if (r.status !== "COMPLETED") out.push(`   (tamper write ${rel}: ${r.status} ${String(r.error).slice(0, 80)})`); };

test("pinning", { timeout: 400000 }, async () => {
  await scenario("C1 ./guard.sh overwrite", ["./guard.sh"], { "guard.sh": SH }, over("guard.sh", SHT));
  await scenario("C2 bash ./guard.sh overwrite", ["bash", "./guard.sh"], { "guard.sh": SH }, over("guard.sh", SHT));
  await scenario("C3 node scripts/guard.js --flag overwrite", ["node", "scripts/guard.js", "--flag"], { "scripts/guard.js": JS }, over("scripts/guard.js", JST));
  await scenario("C4a symlink out of ws (same content)", ["./guard.sh"], { "guard.sh": SH }, async (repo) => { const o = mk("p782o-"); fs.writeFileSync(path.join(o, "g.sh"), SH.replaceAll("LOG", "/dev/null"), { mode: 0o755 }); fs.rmSync(path.join(repo, "guard.sh")); fs.symlinkSync(path.join(o, "g.sh"), path.join(repo, "guard.sh")); });
  await scenario("C4b symlink to in-ws file (tampered content)", ["./guard.sh"], { "guard.sh": SH, "other.sh": SHT }, async (repo) => { fs.rmSync(path.join(repo, "guard.sh")); fs.symlinkSync(path.join(repo, "other.sh"), path.join(repo, "guard.sh")); });
  await scenario("C5 replace parent dir", ["node", "scripts/guard.js"], { "scripts/guard.js": JS }, async (repo) => { fs.renameSync(path.join(repo, "scripts"), path.join(repo, "scripts_old")); fs.mkdirSync(path.join(repo, "scripts")); fs.writeFileSync(path.join(repo, "scripts/guard.js"), JST.replaceAll("LOG", path.join(repo, "..", "x"))); });
  await scenario("C6 arg is a directory (node hookdir)", ["node", "hookdir"], { "hookdir/index.js": JS }, over("hookdir/index.js", JST));
  await scenario("C7 script absent at approval, created later", ["node", "scripts/late.js"], { "keep": "1" }, over("scripts/late.js", JST));
  await scenario("C8 sh -c './guard.sh x'", ["sh", "-c", "./guard.sh x"], { "guard.sh": SH }, over("guard.sh", SHT));
  await scenario("C9 node --require=./pre.js", ["node", "--require=./pre.js", "scripts/guard.js"], { "scripts/guard.js": JS, "pre.js": "" }, over("pre.js", JST));
  await scenario("C10 ../escape", ["../x.sh"], { "guard.sh": SH }, over("guard.sh", SHT));
  await scenario("C11 shell string", "./guard.sh", { "guard.sh": SH }, over("guard.sh", SHT));
  await scenario("C12 2MB script", ["bash", "./big.sh"], { "big.sh": "#!/bin/sh\n" + "#".repeat(2 * 1024 * 1024) + "\nexit 0\n" }, over("big.sh", SHT));
  await scenario("C13 bash -c with -c arg then script path separate", ["bash", "-c", "exec ./guard.sh"], { "guard.sh": SH }, over("guard.sh", SHT));
  console.log("RESULTS\n" + out.join("\n"));
});
EOF
TMPDIR=/dev/shm HOME=$(mktemp -d) node --import tsx --test test/zz_probe_pin.test.ts > /dev/shm/p782/pin.out 2>&1; rtk proxy sed -n '/RESULTS/,/^# /p' /dev/shm/p782/pin.out | cut -c1-520; rtk proxy grep -E "^ℹ (pass|fail)" /dev/shm/p782/pin.out

