import { test } from "node:test";
import fs from "node:fs"; import os from "node:os"; import path from "node:path"; import { createHash } from "node:crypto";
import { approveExtension } from "../src/core/content_trust.js";
import { inspectHookSources } from "../src/core/hooks.js";
import { makeRepo } from "./helpers/fixtures.js";
test("old record", () => {
  process.env.HOME = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "p782h-")));
  const repo = fs.realpathSync(makeRepo({ "guard.sh": "#!/bin/sh\nexit 0\n" })); fs.chmodSync(path.join(repo, "guard.sh"), 0o755);
  for (const cmd of [["./guard.sh"], ["/bin/true"]]) {
    fs.mkdirSync(path.join(repo, ".nexus"), { recursive: true });
    const f = path.join(repo, ".nexus", "hooks.json");
    fs.writeFileSync(f, JSON.stringify({ version: 1, hooks: { "pre-tool": [{ name: "g", tools: ["*"], command: cmd }] } }));
    approveExtension({ kind: "project-hooks", scope: repo, key: ".nexus/hooks.json", sha256: createHash("sha256").update(fs.readFileSync(f)).digest("hex"), approvedAt: new Date().toISOString(), summary: "old" });
    const p = inspectHookSources({ workspace: repo, readOnly: false }).project;
    console.log("OLD", JSON.stringify(cmd), p.status, JSON.stringify(p.changed));
  }
  // malformed files field
  const sp = path.join(process.env.HOME!, ".config", "nexus", "extension_trust.json");
  const doc = JSON.parse(fs.readFileSync(sp, "utf8")); doc.entries[0].files = "x"; fs.writeFileSync(sp, JSON.stringify(doc));
  console.log("OLD malformed files ->", inspectHookSources({ workspace: repo, readOnly: false }).trustProblem);
});
EOF
